 @Override protected void onLayout(boolean changed,int l,int t,int r,int b){super.onLayout(changed,l,t,r,b);int w=r-l,h=b-t;int vw=w,vh=(int)(w/aspect);if(fill&&videoRequested){if(vh<h){vh=h;vw=(int)(h*aspect);}}else if(vh>h){vh=h;vw=(int)(h*aspect);}texture.layout((w-vw)/2,(h-vh)/2,(w+vw)/2,(h+vh)/2);if(videoRequested)poster.layout(0,0,w,h);else{int side=Math.max(0,Math.min(w-dp(32),h-dp(12)));poster.layout((w-side)/2,(h-side)/2,(w+side)/2,(h+side)/2);}}
